**Efficient LLM Inference (KV-Cache):**

```python
class EfficientLLM(nn.Module):
    """LLM with KV-cache for fast generation"""

    def forward(self, input_ids, past_key_values=None, use_cache=True):
        # Only process new tokens!
        if past_key_values is not None:
            input_ids = input_ids[:, -1:]  # Last token only

        x = self.embedding(input_ids)

        # Transformer with caching
        new_past_key_values = []
        for i, layer in enumerate(self.layers):
            past_kv = past_key_values[i] if past_key_values else None
            x, new_kv = layer(x, past_key_values=past_kv, use_cache=use_cache)
            if use_cache:
                new_past_key_values.append(new_kv)

        logits = self.output(x)

        if use_cache:
            return logits, new_past_key_values
        return logits

@torch.no_grad()
def generate_with_cache(model, prompt, max_length=100):
    tokens = tokenizer.encode(prompt)
    past_key_values = None

    for _ in range(max_length):
        # First iteration: Process all tokens
        # Later: Only process new token (cached keys/values)
        input_ids = torch.tensor([tokens]) if past_key_values is None else torch.tensor([[tokens[-1]]])

        logits, past_key_values = model(input_ids, past_key_values=past_key_values)

        next_token = logits[0, -1].argmax().item()
        if next_token == tokenizer.eos_token_id:
            break

        tokens.append(next_token)

    return tokenizer.decode(tokens)

# Much faster! O(n) instead of O(n²)
